#!/usr/bin/env python3
"""Paired CPU experiment. Reference context is generated by the same offline rule core shipped in the app.
No Android LLM integration or independent human scoring is claimed."""
import argparse, json, os, re, subprocess, time, urllib.request, hashlib
from pathlib import Path
p=argparse.ArgumentParser()
p.add_argument('--server',required=True);p.add_argument('--model',required=True);p.add_argument('--out',required=True)
a=p.parse_args();out=Path(a.out);out.mkdir(parents=True,exist_ok=True)
bank=json.loads(Path('research/hybrid_holdout.json').read_text())
assert len(bank)==24 and len({x['id'] for x in bank})==24
node="""const fs=require('fs'),vm=require('vm');const w={},c=vm.createContext({window:w});for(const f of ['teacher_rules.js','teacher.js'])vm.runInContext(fs.readFileSync('app/src/main/assets/'+f,'utf8'),c);const rows=JSON.parse(fs.readFileSync(0,'utf8'));console.log(JSON.stringify({rules:w.WOLFIE_TEACHER.rules.map(({id,title})=>({id,title})),results:rows.map(x=>w.WOLFIE_TEACHER.analyze(x.sentence))}));"""
core=json.loads(subprocess.run(['node','-e',node],input=json.dumps(bank),text=True,capture_output=True,check=True).stdout)
def norm(s):return re.sub(r'[.!?]$','',re.sub(r'\s+',' ',s.strip()).lower().replace('’',"'")) if isinstance(s,str) else s
def equivalent(answer,expected):return isinstance(answer,dict) and answer.get('rule_id')==expected['rule_id'] and 'correction' in answer and norm(answer['correction'])==norm(expected['correction'])
def api(path,payload=None):
    req=urllib.request.Request('http://127.0.0.1:19091'+path,data=None if payload is None else json.dumps(payload).encode(),headers={'Content-Type':'application/json'})
    with urllib.request.urlopen(req,timeout=180) as r:return json.load(r)
def parse(raw):
    raw=re.sub(r'^\s*<think>.*?</think>\s*','',raw,flags=re.S).strip()
    if raw.startswith('```'):raw=re.sub(r'^```(?:json)?\s*|\s*```$','',raw,flags=re.I)
    try:return json.loads(raw)
    except (ValueError,TypeError):return None
with (out/'server.log').open('w') as log:
    proc=subprocess.Popen([a.server,'-m',a.model,'--host','127.0.0.1','--port','19091','-c','4096','-t','4','-ngl','0','--parallel','1','--jinja'],stdout=log,stderr=subprocess.STDOUT)
    try:
        for i in range(120):
            if proc.poll() is not None:raise RuntimeError('server exited')
            try:
                if api('/health').get('status')=='ok':break
            except Exception:time.sleep(1)
        else:raise RuntimeError('server not ready')
        rows=[]
        for item,reference in zip(bank,core['results']):
            candidate={'rule_id':reference['ruleId'],'correction':reference['correction']} if reference['status']=='supported-pattern' else {'rule_id':'unsupported','correction':None}
            for mode in ('base','hybrid'):
                prompt='Correct one sentence ONLY if one of the supported patterns applies. Otherwise return rule_id "unsupported" and correction null; unsupported is not a claim of correctness. Supported rule identifiers: '+json.dumps(core['rules'],ensure_ascii=False)+'. Return one JSON object with rule_id, correction, explanation_ru. Explain in Russian without inventing grammar rules. Input: '+item['sentence']
                if mode=='hybrid':
                    prompt+='\nVerified offline reference for this input (do not contradict it): '+json.dumps(reference,ensure_ascii=False)
                start=time.monotonic()
                result=api('/v1/chat/completions',dict(model='local',messages=[dict(role='system',content='You are a careful English teacher. Return only the requested JSON. Admit uncertainty.'),dict(role='user',content=prompt+'\n/no_think')],temperature=0,seed=42,max_tokens=512,stream=False))
                choice=result['choices'][0];raw=choice['message']['content'];parsed=parse(raw);validated=equivalent(parsed,candidate) if mode=='hybrid' else None
                rows.append(dict(id=item['id'],level=item['level'],mode=mode,expected=item['expected'],reference=candidate,core_correct=equivalent(candidate,item['expected']),raw=raw,parsed=parsed,raw_objective_correct=equivalent(parsed,item['expected']),validator_accepts=validated,hybrid_delivered=candidate if mode=='hybrid' else None,hybrid_delivery_correct=equivalent(candidate,item['expected']) if mode=='hybrid' else None,explanation_status='HUMAN_REVIEW_REQUIRED',finish_reason=choice.get('finish_reason'),seconds=round(time.monotonic()-start,3)))
                (out/'responses.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
        summary={'model':Path(a.model).name,'model_bytes':Path(a.model).stat().st_size,'model_sha256':hashlib.file_digest(open(a.model,'rb'),'sha256').hexdigest(),'cases':len(bank),'base_raw_correct':sum(r['raw_objective_correct'] for r in rows if r['mode']=='base'),'hybrid_raw_correct':sum(r['raw_objective_correct'] for r in rows if r['mode']=='hybrid'),'hybrid_validator_accepted':sum(r['validator_accepts'] is True for r in rows),'hybrid_delivered_correct':sum(r['hybrid_delivery_correct'] is True for r in rows),'truncated':sum(r['finish_reason']=='length' for r in rows),'seconds':round(sum(r['seconds'] for r in rows),3),'memory':[x for x in Path(f'/proc/{proc.pid}/status').read_text().splitlines() if x.startswith(('VmRSS:','VmHWM:'))],'explanation_quality':'NOT_INDEPENDENTLY_SCORED','runtime':'Linux CPU, not Android'}
        (out/'summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary))
    finally:
        proc.terminate()
        try:proc.wait(timeout=10)
        except subprocess.TimeoutExpired:proc.kill();proc.wait()
